ROLL_SP  = 10.0;
PITCH_SP = 10.0;

%% ── Pre-computed step times & metrics ───────────────────────────────────────
t_roll_step   = 2.0400;
t_roll_return = 4.7050;
t_pitch_step  = 9.5400;
t_pitch_return= 12.2000;

os_roll_pct  = 0.0;   rise_roll  = 0.2950;  settle_roll  = 2.6600;  peak_roll  = 9.6760;
os_pitch_pct = 0.0;   rise_pitch = 0.2850;  settle_pitch = 2.6550;  peak_pitch = 9.6930;

tau_roll  = rise_roll  / 2.2;
tau_pitch = rise_pitch / 2.2;

%% ── Reference curves ─────────────────────────────────────────────────────────
roll_ref  = zeros(size(T));
pitch_ref = zeros(size(T));

mask_rr  = T >= t_roll_step   & T < t_roll_return;
mask_rrt = T >= t_roll_return;
roll_ref(mask_rr)  = ROLL_SP  * (1 - exp(-(T(mask_rr)  - t_roll_step)   / tau_roll));
roll_ref(mask_rrt) = ROLL_SP  *      exp(-(T(mask_rrt) - t_roll_return)  / tau_roll);

mask_pr  = T >= t_pitch_step  & T < t_pitch_return;
mask_prt = T >= t_pitch_return;
pitch_ref(mask_pr)  = PITCH_SP * (1 - exp(-(T(mask_pr)  - t_pitch_step)  / tau_pitch));
pitch_ref(mask_prt) = PITCH_SP *      exp(-(T(mask_prt) - t_pitch_return) / tau_pitch);

roll_sp  = zeros(size(T));
pitch_sp = zeros(size(T));
roll_sp( mask_rr)  = ROLL_SP;
pitch_sp(mask_pr) = PITCH_SP;

%% ── Colours ──────────────────────────────────────────────────────────────────
cRoll  = [0.20 0.45 0.85];
cPitch = [0.90 0.55 0.10];
cGray  = [0.50 0.50 0.50];

%% ── Figure: 2-row layout ─────────────────────────────────────────────────────
fig = figure('Name','B3 — Attitude step response','Position',[60 60 1120 720]);
LFT=0.10; WID=0.82; BOT_LO=0.09; HGT_LO=0.36; GAP=0.10;
BOT_UP=BOT_LO+HGT_LO+GAP; HGT_UP=0.36;

%% ── (a) Roll ─────────────────────────────────────────────────────────────────
ax1 = axes('Position',[LFT BOT_UP WID HGT_UP]);
hold on;
plot(ax1, T, roll,     '-',  'Color',cRoll, 'LineWidth',1.5, 'DisplayName','Roll (measured)');
plot(ax1, T, roll_sp,  '--', 'Color',[cRoll 0.5], 'LineWidth',1.0, 'DisplayName','Roll setpoint');
plot(ax1, T, roll_ref, ':',  'Color',cGray, 'LineWidth',1.2, ...
     'DisplayName', sprintf('1st-order ref (\tau=%.3f s) [Ref 1]', tau_roll));
xline(ax1, t_roll_step,   ':', 'Color',cGray, 'LineWidth',1.0, 'HandleVisibility','off');
xline(ax1, t_roll_return, ':', 'Color',cGray, 'LineWidth',1.0, 'HandleVisibility','off');
text(ax1, t_roll_step+0.8, peak_roll+2.0, ...
     sprintf('Overshoot=%.1f%%\nRise=%.4f s\nSettle=%.3f s', os_roll_pct, rise_roll, settle_roll), ...
     'FontSize',16, 'Color',cRoll, 'BackgroundColor',[1 1 .88], 'EdgeColor',[.7 .7 .5], 'Margin',3);
set(ax1,'XLim',[0 T(end)],'YLim',[-5 18],'Box','off', ...
        'YGrid','on','XGrid','off','GridAlpha',.25,'GridLineStyle','--','XTickLabel',{});
ylabel(ax1,'Roll angle  (deg)','FontSize',25);
title(ax1, {'EXP-B3: Attitude Step Response — Roll and Pitch'; ...
            'Literature benchmark: rise 0.1-0.5 s, overshoot <10%, settle <0.5 s [Ref 4]'}, ...
      'FontSize',25);
legend(ax1, 'FontSize',16, 'Location','best', 'Box','off');
hold off;

%% ── (b) Pitch ────────────────────────────────────────────────────────────────
ax2 = axes('Position',[LFT BOT_LO WID HGT_LO]);
hold on;
plot(ax2, T, pitch,     '-',  'Color',cPitch, 'LineWidth',1.5, 'DisplayName','Pitch (measured)');
plot(ax2, T, pitch_sp,  '--', 'Color',[cPitch 0.5], 'LineWidth',1.0, 'DisplayName','Pitch setpoint');
plot(ax2, T, pitch_ref, ':',  'Color',cGray, 'LineWidth',1.2, ...
     'DisplayName', sprintf('1st-order ref (\tau=%.3f s) [Ref 1]', tau_pitch));
xline(ax2, t_pitch_step,   ':', 'Color',cGray, 'LineWidth',1.0, 'HandleVisibility','off');
xline(ax2, t_pitch_return, ':', 'Color',cGray, 'LineWidth',1.0, 'HandleVisibility','off');
text(ax2, t_pitch_step+0.8, peak_pitch+2.0, ...
     sprintf('Overshoot=%.1f%%\nRise=%.4f s\nSettle=%.3f s', os_pitch_pct, rise_pitch, settle_pitch), ...
     'FontSize',16, 'Color',cPitch, 'BackgroundColor',[1 1 .88], 'EdgeColor',[.7 .7 .5], 'Margin',3);
set(ax2,'XLim',[0 T(end)],'YLim',[-5 18],'Box','off', ...
        'YGrid','on','XGrid','off','GridAlpha',.25,'GridLineStyle','--');
xlabel(ax2,'Time  (s)','FontSize',25);
ylabel(ax2,'Pitch angle  (deg)','FontSize',25);
legend(ax2, 'FontSize',16, 'Location','best', 'Box','off');
hold off;

linkaxes([ax1 ax2], 'x');
